html:
{%- set c = offer_letter_context(doc.name) -%}
<div style="font-family: Georgia, 'Times New Roman', serif; color: #1a1a1a; max-width: 720px; margin: 0 auto; font-size: 11pt; line-height: 1.5;">
  <p style="text-align: right;">{{ frappe.utils.formatdate(c.offer_date) if c.offer_date else "" }}</p>
  <p><strong>{{ c.applicant_name }}</strong></p>
  <h3 style="margin: 1.5rem 0 1rem;">Offer of employment: {{ c.designation }}</h3>
  <table style="width: 100%; border-collapse: collapse; margin-bottom: 1rem;">
    <tr><td style="width: 35%; padding: 4px 0; color: #555;">Post</td><td>{{ c.designation }}</td></tr>
    <tr><td style="padding: 4px 0; color: #555;">Department</td><td>{{ c.department or "To be confirmed" }}</td></tr>
    <tr><td style="padding: 4px 0; color: #555;">Grade</td><td>{{ c.grade or "To be confirmed" }}</td></tr>
    <tr><td style="padding: 4px 0; color: #555;">Start date</td><td>{{ c.start_date or "To be agreed" }}</td></tr>
    <tr><td style="padding: 4px 0; color: #555;">Please accept by</td><td>{{ c.accept_by or "See below" }}</td></tr>
    {%- for t in c.terms %}
    <tr><td style="padding: 4px 0; color: #555;">{{ t.label }}</td><td>{{ t.value }}</td></tr>
    {%- endfor %}
  </table>
  {%- if c.wording %}
  <div>{{ c.wording }}</div>
  {%- else %}
  <p style="color: #a15c00;">{{ c.wording_awaiting }}</p>
  {%- endif %}
  {%- if doc.terms %}
  <div style="margin-top: 1rem;">{{ doc.terms }}</div>
  {%- endif %}
  <p style="margin-top: 2.5rem;">Yours sincerely,</p>
  <p style="margin-top: 2.5rem;{% if c.signatory_awaiting %} color: #a15c00;{% endif %}">{{ c.signatory }}</p>
</div>
